import random,heapq,math,exact,json,time

def build_brute(fab,cal):
 n,T,S,P,V=fab.n,fab.T,fab.S,fab.P,fab.V
 def adj(g):
  A=[[] for _ in range(V)]
  for p in range(P):
   r=fab.rho[p]
   for l in fab.active_by_phase[p]:
    link=fab.links[l]; ends=link['ends']; ds=link['delay_ns']; dfs=link['defer_rounds']
    for dr in (0,1):
     if dr==0: sg,ss,sn=ends[0][2],ends[0][1],ends[0][0]; dg,dd,dn=ends[1][2],ends[1][1],ends[1][0]
     else: sg,ss,sn=ends[1][2],ends[1][1],ends[1][0]; dg,dd,dn=ends[0][2],ends[0][1],ends[0][0]
     delay=ds[dr];defer=dfs[dr]
     if not min(r,S-r-delay)>=g: continue
     # black
     k=(delay+T-1)//T;bad=False
     for j in range(k):
      for rec in fab.blackouts:
       if rec[0]==l and rec[1]<=((p+j)%P)<rec[2]:bad=True
     if bad:continue
     q=(p+k+defer)%P; dest=q*n+dn
     aging=(k*T-delay)*fab.eff[((p+k-1)%P)*n+dn]
     for jj in range(k,k+defer):aging+=T*fab.eff[((p+jj)%P)*n+dn]
     cb=cal.hop_as[sg][dg]+aging;ca=k+defer
     A[p*n+sn].append((dest,cb,ca,2*l+dr))
  return A
 return adj

def brute(fab,cal):
 V=fab.V;n=fab.n;P=fab.P;A=build_brute(fab,cal);outs=[]
 for g in fab.guards:
  Adj=A(g);dist=[None]*V;h=[]
  for v in fab.anchor_ids:dist[v]=(0,0);heapq.heappush(h,(0,0,v))
  while h:
   b,a,v=heapq.heappop(h)
   if dist[v]!=(b,a):continue
   p=v//n;i=v%n;dv=((p+1)%P)*n+i;c=(b+fab.eff[v]*fab.T,a+1)
   if dist[dv] is None or c<dist[dv]:dist[dv]=c;heapq.heappush(h,(*c,dv))
   for dv,cb,ca,code in Adj[v]:
    c=(b+cb,a+ca)
    if dist[dv] is None or c<dist[dv]:dist[dv]=c;heapq.heappush(h,(*c,dv))
  pe=None
  if all(d is not None for d in dist):pe=max(dist[v][0]+fab.eff[v]*fab.T for v in range(V))
  outs.append(pe)
 return outs

def rand_profile(maxK=5):
 K=random.randint(1,maxK)
 x=[random.randint(-5,5) for _ in range(K)]
 meas=[]
 if K>1:
  for b in range(1,K): meas.append([random.randrange(b),b,0,0])
 # choose feasible intervals via random constraints from x, ensure no inconsistency
 for _ in range(random.randint(0,15)):
  a=random.randrange(K);b=random.randrange(K)
  d=x[b]-x[a]
  meas.append([a,b,d-random.randint(0,5),d+random.randint(0,5)])
 return {'groups':K,'jitter_ps':[random.randint(0,5) for _ in range(K)],'measurements':meas}

for it in range(2000):
 calc=rand_profile()
 cal=exact.solve_calibration(calc);assert cal.feasible
 n=random.randint(1,5)
 T=random.randint(1,8);S=random.randint(1,15);O=random.randrange(S);Q=random.randint(1,4)
 M=Q*S;P=M//math.gcd(T,M)
 # create links with port groups consistent per node/slot
 L=0 if n<2 else random.randint(0,10)
 links=[];port_group={}
 for l in range(L):
  a,b=random.sample(range(n),2)
  sa=random.randrange(4);sb=random.randrange(4)
  ga=port_group.setdefault((a,sa),random.randrange(calc['groups']))
  gb=port_group.setdefault((b,sb),random.randrange(calc['groups']))
  links.append({'ends':[[a,sa,ga],[b,sb,gb]],'delay_ns':[random.randint(1,8*T),random.randint(1,8*T)],'defer_rounds':[random.randint(0,8),random.randint(0,8)]})
 slices=[]
 for q in range(Q):
  # random subset respecting no shared port by rejection
  used=set();ids=[]
  for l in random.sample(range(L),L):
   link=links[l];ports=[]
   for e in link['ends']:ports.append((e[0],e[1]))
   if any(pp in used for pp in ports):continue
   used.update(ports);ids.append(l)
  slices.append(ids)
 heat=[]
 for _ in range(random.randint(0,4)):
  if P>0:
   a=random.randrange(P);b=random.randint(a+1,P);heat.append([random.randrange(n),a,b,random.randint(0,5)])
 anchors=[]
 for _ in range(random.randint(0,4)):
  a=random.randrange(P);b=random.randint(a+1,P);anchors.append([random.randrange(n),a,b])
 blackouts=[]
 for _ in range(random.randint(0,4)):
  if L:
   a=random.randrange(P);b=random.randint(a+1,P);blackouts.append([random.randrange(L),a,b])
 gmax=max(1,(S-1)//2)
 vals=sorted(random.sample(range(gmax+1),k=min(4,gmax+1)))
 f={'n':n,'interval_ns':T,'slice_ns':S,'offset_ns':O,'drift_ppb':[random.randint(0,8) for _ in range(n)],'heat':heat,'anchors':anchors,'links':links,'slices':slices,'blackouts':blackouts,'guards_ns':vals,'reconfig_ns':random.randint(0,5)}
 fab=exact.Fabric(f)
 comp=exact.compute_plan_exact(fab,cal)
 br=brute(fab,cal)
 if comp['peaks_by_index']!=br:
  print('MISMATCH',it,comp['peaks_by_index'],br,json.dumps(f),calc);break
else:
 print('independent random plan formula/dynamic compare ok')
